mapper.select:
SELECT account_num, is_consent, seqno, is_foreign_deposit, prod_name, is_minus, account_type, account_status,ci
FROM mock_account
WHERE ci = #{ci}
ORDER BY account_num, seqno
LIMIT #{limit} OFFSET #{offset}

SELECT d.currency_code, d.balance_amt, d.withdrawable_amt, d.offered_rate, d.last_paid_in_cnt
FROM mock_account_detail d
JOIN mock_account a ON a.account_num = d.account_num AND a.seqno = d.seqno
WHERE a.org_code = #{orgCode} AND d.account_num = #{accountNum}
AND d.seqno = #{seqno}

SELECT t.trans_dtime, t.trans_no, t.trans_type, t.trans_class, t.currency_code,
       t.trans_amt, t.balance_amt, t.paid_in_cnt, t.trans_memo,
       t.category_code AS category
FROM mock_account_transaction t
JOIN mock_account a ON a.account_num = t.account_num AND a.seqno = t.seqno
WHERE a.org_code = #{orgCode}
  AND t.account_num = #{accountNum}
  AND t.trans_dtime BETWEEN CONCAT(#{fromDate}, '000000') AND CONCAT(#{toDate}, '235959')
  AND t.seqno = #{seqno}
ORDER BY t.trans_dtime DESC, t.trans_no DESC
LIMIT #{limit} OFFSET #{offset}
